r=pathlib.Path(__file__).parent;c=Corpus(r/'data');index=LegalIndex(c)
slides=[
('ОПОРА 3.0','Прямой юридический вывод с проверяемыми основаниями','VIBESECURITY / Hack&Change 2026 / Трек ПСБ','Код: https://github.com/antonshkelll/opora-psb\nВитрина: https://antonshkelll.github.io/opora-psb/\nПроверка: вопрос → вывод → основание → документ'),
('От вопроса к решению','Юристу нужно применить норму к конкретной ситуации','Найти похожий документ недостаточно.\nНужно проверить договор, дату, исключение и факты вопроса.\n\nОПОРА формирует прямой вывод и показывает его основания.\nЕсли условия неизвестны: запрашивает конкретный документ или дату.','Источник задачи: кейс ПСБ и предоставленный корпус.'),
('Что меняет версия 3','Вывод проверяется вместе с доказательствами','Модель формулирует короткие выводы и выбирает ID абзацев.\nПрограмма проверяет существование оснований и новые числа.\n\nСинтезированные и рискованные ответы проходят смысловую проверку.\nОна может исправить неверный вывод до выдачи пользователю.','Проверяющая модель тоже может ошибаться. Это снижение риска, не гарантия точности.'),
('Противоположное «да» не проходит молча','Четыре рабочих дня при максимуме трёх','В V2 наличие правильной цитаты не доказывало правильность «да/нет».\n\nВ V3 смысловая проверка сопоставляет вывод с вопросом и нормой.\nКонтрольный тест возвращает ошибочное «да» и требует исправить его.\n\nПри отказе проверки ответ получает техническое состояние.','Тест с имитатором API проверяет поведение программы, не частоту ошибок реальной модели.'),
('Дата из календаря имеет значение','ISO-дата и привычная запись дают один результат','Поддержаны YYYY-MM-DD и DD.MM.YYYY.\nРегламент выбирается по явно указанной дате события.\n\nНеприменимая редакция исключается до вызова модели.\nПри сравнении редакций доступны обе.\nСтарый год сам по себе больше не вызывает автоматический отказ.','Историческую норму нельзя восстанавливать по памяти; применимость проверяется по доступным данным.'),
('Несколько оснований для одного вывода','Исключения должны доходить до ответа','Снят порог 45% от лучшего поискового совпадения.\nДо четырёх фрагментов одного документа вместо двух.\n\nУвеличен контекст длинных нормативных блоков.\nМожно выбрать до 12 абзацев для шести выводов.\nУ каждого вывода собственный список доказательств.','Поиск остаётся лексическим; новые эмбеддинги без проверенного API не заявляются.'),
('Рабочее пространство юриста','Вывод, существенные условия и документы рядом','Откройте ситуацию и проверьте основание в полном документе.\nДата события задаётся отдельно от текста вопроса.\n\nПубличная витрина показывает примеры организаторов.\nЖивое приложение принимает новые вопросы через настроенную модель.','Статическая демонстрация не выдаётся за живые ответы V3.'),
('Проверка версии','Измерения отделены от обещаний','35 автоматических тестов активного пути V3.\nПроверены даты, редакции, смысловой отказ и исправление вывода.\n\nОтдельный тест запускает упакованный скрипт через HTTP\nи проверяет CSV с кириллицей, запятыми и историей.\n\nНовый балл V3 подтверждается только платформой.','Результат V2: 24 балла и 172,6 секунды по скриншоту команды. Цель следующей итерации: 51.'),
('Запуск и сдача','Два пакета версии 3','Первый тур: opora-submit-v3.zip.\nЧетыре корневых файла, модель и база приходят от платформы.\n\nФинал: opora-final-v3.zip с Docker, базой, тестами и PDF.\nЖивое приложение: docker compose up --build -d.','Ограничения: ZIP до 128 МБ, 20 минут, 8 CPU, 16 ГБ RAM, 5 попыток/сутки.'),
('Следующий шаг','Независимая оценка юристами','Проверять правильность вывода, полноту исключений,\nнеподтверждённые добавления и ложные отказы.\n\nНе называть совпадение ключевых слов юридической точностью.\nПеред банковским пилотом: права доступа, SSO и журнал аудита.','Экономия времени и денежный эффект пока не измерены.'),
('Ответственность','Роли согласованы с Антоном','Антон Шкель: архитектура, требования и общая приёмка\nМарина Зайцева: юридические сценарии\nИрина Ершова: поиск и оценка качества\nВиктор Елкин: запуск, API и упаковка\nАмина Темирлиева: интерфейс и защита','Согласованные роли не подменяют подтверждение фактического вклада.')]
payload=[dict(zip(['title','subtitle','body','foot'],s)) for s in slides]
for name in ['docs/slides.json','web/slides.json']:(r/name).write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf-8')
with (r/'data/demo_questions.csv').open(encoding='utf-8-sig',newline='') as f:questions=list(csv.DictReader(f))
with (r/'data/demo_output.csv').open(encoding='utf-8-sig',newline='') as f:answers={x['id']:x['answer'] for x in csv.DictReader(f)}
expected=['D01','D20',None,'D01','D06','D02','D01','D02','D03','D07','D08','D20','D09','D19','D01','D02','D03','D07']
cases=[]
for q,did in zip(questions,expected):
 doc=next((d for d in c.docs if d['id']==did),None)
 evidence=[{'doc_id':did,'title':doc['title'],'quote':doc['text'],'provision':'Полный документ для проверки контекста'}] if doc else []
 cases.append({'id':q['id'],'question':q['question'],'answer':answers[q['id']],'status':'partial' if did is None else 'answered','verdict':'','evidence':evidence})
(r/'web/demo.json').write_text(json.dumps({'type':'organizer_reference_examples','notice':'Опубликованные учебные ответы организаторов, не генерация V3.','cases':cases,'documents':c.docs},ensure_ascii=False),encoding='utf-8')
p=r/'web/app.js';s=p.read_text(encoding='utf-8');s=s.replace('Сохранённый реальный прогон Qwen3.5 4B. Страница не запускает генерацию; это не оценка DeepSeek.','Учебный ответ из материалов организаторов. Это пример, не результат генерации V3.').replace('Сохранённые ответы реальной локальной Qwen3.5 4B на 18 опубликованных вопросах. На этой странице генерация не запускается. Это не ответы DeepSeek и не оценка закрытого теста. В живом приложении те же экраны принимают новые вопросы.','18 опубликованных примеров организаторов. Это учебная витрина, а не ответы новой модели. Для новых вопросов используйте подключённое приложение.').replace('<b>40</b><span>тестов кода','<b>35</b><span>тестов кода').replace('demo.json?v=2','demo.json?v=3');p.write_text(s,encoding='utf-8')
p=r/'web/index.html';p.write_text(re.sub(r'src="app.js[^"]*"','src="app.js?v=3"',p.read_text(encoding='utf-8')),encoding='utf-8')
print('V3 slides and clearly labelled reference showcase rebuilt; units:',len(index.units))
